import React, { useContext, useEffect, useState } from "react";
import { AuthContext } from "../Context/AuthContext";
import { useNavigate } from "react-router-dom";
import axios from "axios";

let initState = {
  email: "",
  password: "",
};

export default function Login() {
  const [email, setEmail] = useState(initState.email);
  const [password, setPassword] = useState(initState.password);
  const [userData, setUserData] = useState([]);
  const Auth = useContext(AuthContext);
  const navigate = useNavigate();

  function fetchUserData() {
    axios
      .get(`https://rctmockapi.onrender.com/user`)
      .then((res) => {
        setUserData(res.data);
      })
      .catch((err) => {
        console.log(err);
      });
  }

  function handleSubmit(e) {
    e.preventDefault();
    let found = false;
    userData.forEach((user) => {
      if (user.email === email && user.password === password) {
        found = true;
        Auth.loginUser(user.name);
        navigate("/");
      }
    });
    if (!found && userData.length > 0) {
      alert("Invalid email or password");
    }
  }

  useEffect(() => {
    fetchUserData();
  }, []);

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-4 py-12">
      <div className="bg-[#304b62] w-full max-w-[420px] rounded-2xl shadow-xl p-8 md:p-10">
        <h1 className="text-2xl md:text-3xl font-extrabold text-white mb-6 text-center md:text-left">
          Log In
        </h1>

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-white font-medium text-sm md:text-base mb-2">
              Email address <span className="text-red-300">*</span>
            </label>
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-white text-slate-800 text-base md:text-lg px-4 py-2.5 rounded-md border border-transparent focus:outline-none focus:ring-2 focus:ring-[#d49539]"
              placeholder="name@example.com"
            />
          </div>

          <div>
            <label className="block text-white font-medium text-sm md:text-base mb-2">
              Password <span className="text-red-300">*</span>
            </label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-white text-slate-800 text-base md:text-lg px-4 py-2.5 rounded-md border border-transparent focus:outline-none focus:ring-2 focus:ring-[#d49539]"
              placeholder="••••••••"
            />
          </div>

          <div className="pt-4 flex flex-col sm:flex-row items-center gap-4">
            <button
              type="submit"
              className="w-full sm:w-auto bg-[#d49539] hover:bg-[#c0832d] text-white font-bold py-2.5 px-6 rounded-md transition-colors shadow-md text-base"
            >
              Submit
            </button>
            <button
              type="button"
              onClick={() => navigate("/signup")}
              className="w-full sm:w-auto border border-[#d49539] text-[#d49539] hover:bg-[#d49539]/10 font-medium py-2.5 px-4 rounded-md transition-colors text-sm md:text-base text-center"
            >
              Not Registered yet?
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
